// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address caller, address recipient) public {
        vm.assume(caller != address(this));
        vm.assume(recipient != address(this));
        vm.assume(recipient != address(c));

        vm.deal(address(c), 1 ether);

        uint256 balanceBefore = address(c).balance;

        bool didRevert = false;
        vm.prank(caller);
        try c.withdrawAll(recipient) {
        } catch {
            didRevert = true;
        }

        if (!didRevert) {
            uint256 balanceAfter = address(c).balance;
            bool balanceIsZero = (balanceAfter == 0);
            bool callerIsOwner = (caller == address(this));
            assertTrue(balanceIsZero == callerIsOwner);
        } else {
            assertTrue(address(c).balance == balanceBefore);
        }
    }
}
